{
  "components": [
    {
      "type": "claim",
      "quote": "In Switzerland no one person is ever head of state.",
      "gist": "Switzerland has no single permanent head of state."
    },
    {
      "type": "claim",
      "quote": "The president of the Confederation is 'primus inter pares' – first among equals – for one year, but with the office there still comes a whole series of traditional duties and tasks.",
      "gist": "Swiss Confederation president serves one year as first among equals with traditional duties."
    },
    {
      "type": "obligation",
      "quote": "The President of the Swiss Confederation is elected for one year of office by the United Federal Assembly.",
      "gist": "The United Federal Assembly elects the Swiss Confederation president for one year."
    },
    {
      "type": "claim",
      "quote": "Even though the title suggests otherwise, the president of the Swiss Confederation is not head of state.",
      "gist": "Despite the title, the Swiss Confederation president is not the head of state."
    }
  ]
}
